/**
 * The `pdb rules init` starter (#516, doc/design/native-project-rules.md "Configuration,
 * identity, English and packaging"): a reviewable native policy bound to the shipped policy
 * this installation runs, never a copy of a stale example. Writing it enables nothing.
 */
export function starterProjectRules(base: { policyVersion: number; rulesHash: string }): string {
  return `;; Native project preferences for pdb (doc/design/native-project-rules.md).
;; Generated by pdb rules init for the shipped policy below. Review and commit this file, then
;; enable it explicitly: pdb config set rules.project.enabled true
;; Preferences only reorder actions the shipped policy already admitted, within a band.
{:format-version 1
 :projection-version 1
 :base-policy-version ${base.policyVersion}
 :base-rules-hash "${base.rulesHash}"
 :rules [[(project-hotfix ?a) [?a "pdb.action-label" "project:priority"]]]
 :preferences [{:id "project-hotfix"
                :when [(project-hotfix ?a)]
                :priority [[(+ 0 10) ?value]]
                :why "Project priority label matched: {label}."
                :witnesses {"label" [[?a "pdb.action-label" "project:priority"]
                                     [(str "project:priority") ?value]]}}]}
`;
}
